	/**
	 * 保持するコンテナのListを返します。
	 *
	 * @return コンテナのList
	 */
	public List<MCContainer> getContainers(){
		List<MCContainer> ret = super.getContainers();
		if(!MCCollectionUtil.contains(ret, getMstR())) ret.add(getMstR());
		if(!MCCollectionUtil.contains(ret, getCndR())) ret.add(getCndR());
		if(!MCCollectionUtil.contains(ret, getCmnR())) ret.add(getCmnR());
		if(!MCCollectionUtil.contains(ret, getImgL())) ret.add(getImgL());
		if(!MCCollectionUtil.contains(ret, getSubDtlL())) ret.add(getSubDtlL());
		if(!MCCollectionUtil.contains(ret, getUnitDtlL())) ret.add(getUnitDtlL());
		if(!MCCollectionUtil.contains(ret, getLclDtlL())) ret.add(getLclDtlL());
		if(!MCCollectionUtil.contains(ret, getDtlL())) ret.add(getDtlL());
		return ret;
	}

	/**
	 * コンテナに対応したブロックのIDを返します。
	 *
	 * 引数のコンテナに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return ブロックID
	 */
	public String getBlockId(MCContainer aCnt){
		if(aCnt == null) return null;
		if(aCnt == getMstR()) return "Mst";
		if(aCnt == getCndR()) return "Cnd";
		if(aCnt == getCmnR()) return "Cmn";
		if(aCnt == getImgL()) return "Img";
		if(aCnt == getSubDtlL()) return "SubDtl";
		if(aCnt == getUnitDtlL()) return "UnitDtl";
		if(aCnt == getLclDtlL()) return "LclDtl";
		if(aCnt == getDtlL()) return "Dtl";
		return super.getBlockId(aCnt);
	}

	/**
	 * ブロックIDに対応したコンテナを返します。
	 *
	 * 引数のブロックIDに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return コンテナ
	 */
	public MCContainer getContainer(String bId){
		if(bId == null) return null;
		if(bId.equals("Mst")) return getMstR();
		if(bId.equals("Cnd")) return getCndR();
		if(bId.equals("Cmn")) return getCmnR();
		if(bId.equals("Img")) return getImgL();
		if(bId.equals("SubDtl")) return getSubDtlL();
		if(bId.equals("UnitDtl")) return getUnitDtlL();
		if(bId.equals("LclDtl")) return getLclDtlL();
		if(bId.equals("Dtl")) return getDtlL();
		return super.getContainer(bId);
	}

