	/**
	 * この画面のステータスを設定します。
	 *
	 * @param status ステータス
	 */
	public void setStatus(String status) {
		super.setStatus(status);
		if (UPD.equals(status)) {
			setUPDStatus();
		}
		else if (SRCH.equals(status)) {
			setSRCHStatus();
		}
		else if (MOD.equals(status)) {
			setMODStatus();
		}
		else if (UPD_ADMIN.equals(status)) {
			setUPD_ADMINStatus();
		}
		else if (REF.equals(status)) {
			setREFStatus();
		}
		else if (FIX_U.equals(status)) {
			setFIX_UStatus();
		}
		else if (FIX.equals(status)) {
			setFIXStatus();
		}
		else if (RELEASE.equals(status)) {
			setRELEASEStatus();
		}
		else if (RELEASE_ADMIN.equals(status)) {
			setRELEASE_ADMINStatus();
		}
	}

